def seed_db():
    conn = pymysql.connect(
        host='localhost',
        port=3306,
        user='root',
        password='0506',
        database='mdagroconnect',
        charset='utf8',
        autocommit=True
    )
    with conn.cursor() as cur:
        for p in PRODUCTS_DATA:
            tags_json = json.dumps(p['tags'])
            cur.execute("""
                INSERT INTO products (id, name, category, price, unit, rating, reviews, description, image, tags, in_stock)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
                ON DUPLICATE KEY UPDATE
                    name = VALUES(name),
                    category = VALUES(category),
                    price = VALUES(price),
                    unit = VALUES(unit),
                    rating = VALUES(rating),
                    reviews = VALUES(reviews),
                    description = VALUES(description),
                    image = VALUES(image),
                    tags = VALUES(tags),
                    in_stock = VALUES(in_stock)
            """, (
                p['id'], p['name'], p['category'], p['price'], p['unit'],
                p['rating'], p['reviews'], p['description'], p['image'], tags_json, p['in_stock']
            ))
        cur.execute("SELECT COUNT(*) FROM products")
        cnt = cur.fetchone()[0]
        print(f"Successfully seeded! Total products in DB now: {cnt}")
    conn.close()

if __name__ == '__main__':
    seed_db()
